// Pure core for sat-score-percentiles-mcp. No I/O: every number comes from src/sat.data.ts,
// generated by scripts/build_data.py from College Board sources fetched 2026-11-03.
import { NATIONAL_2026, PERCENTILE_SOURCE, SECTION_PERCENTILES, STATES_2026, TOTAL_PERCENTILES } from './sat.data.js';
export const REPO = 'sat-score-percentiles-mcp';
export const SITE = 'https://examscorecalc.com';
export const UTM = `utm_source=mcp&utm_medium=${REPO}`;
export const DATA_DATE = '2026-11-03';
export const REPORT_PAGE = 'https://reports.collegeboard.org/sat-suite-program-results';
export const link = (path) => `${SITE}${path}?${UTM}`;
export const MORE_SAT = link('/sat/');
export const MORE_CALC = link('/digital-sat-score-calculator/');
export class InputError extends Error {
}
const SECTION_NAMES = { total: 'Total score (400-1600)', rw: 'Reading and Writing section (200-800)', math: 'Math section (200-800)' };
export function resolveSection(s) {
    const k = s.trim().toLowerCase().replace(/[^a-z]/g, '');
    if (['total', 'composite', 'overall', 'combined'].includes(k))
        return 'total';
    if (['rw', 'erw', 'reading', 'readingandwriting', 'readingwriting', 'verbal', 'english'].includes(k))
        return 'rw';
    if (['math', 'maths', 'mathematics'].includes(k))
        return 'math';
    throw new InputError(`Unknown section "${s}". Use total, rw (Reading and Writing) or math.`);
}
export function checkScore(score, section) {
    const [lo, hi] = section === 'total' ? [400, 1600] : [200, 800];
    if (!Number.isInteger(score) || score < lo || score > hi || score % 10 !== 0) {
        throw new InputError(`${SECTION_NAMES[section]} scores run from ${lo} to ${hi} in steps of 10. Got ${score}.`);
    }
    return score;
}
/** "99+" means above the 99th percentile, "1-" below the 1st. */
export function pctNumber(p) {
    if (p.endsWith('+'))
        return Number(p.slice(0, -1)) + 0.5;
    if (p.endsWith('-'))
        return Number(p.slice(0, -1)) - 0.5;
    return Number(p);
}
export function percentiles(score, section) {
    if (section === 'total') {
        const r = TOTAL_PERCENTILES[score];
        return { nationally_representative: r.nat, user_group: r.user };
    }
    const r = SECTION_PERCENTILES[score];
    return section === 'rw' ? { nationally_representative: r.rw_nat, user_group: r.rw_user } : { nationally_representative: r.math_nat, user_group: r.math_user };
}
const ordinal = (p) => {
    if (p.endsWith('+'))
        return `above the ${p.slice(0, -1)}th`;
    if (p.endsWith('-'))
        return 'below the 1st';
    const n = Number(p);
    const s = n % 100 >= 11 && n % 100 <= 13 ? 'th' : { 1: 'st', 2: 'nd', 3: 'rd' }[n % 10] ?? 'th';
    return `${n}${s}`;
};
function bandFor(score) {
    return NATIONAL_2026.total_score_bands.find((b) => { const [lo, hi] = b.band.split('-').map(Number); return score >= lo && score <= hi; }) ?? null;
}
const STATE_CODES = {
    AL: 'Alabama', AK: 'Alaska', AZ: 'Arizona', AR: 'Arkansas', CA: 'California', CO: 'Colorado', CT: 'Connecticut', DE: 'Delaware', DC: 'District of Columbia',
    FL: 'Florida', GA: 'Georgia', HI: 'Hawaii', ID: 'Idaho', IL: 'Illinois', IN: 'Indiana', IA: 'Iowa', KS: 'Kansas', KY: 'Kentucky', LA: 'Louisiana', ME: 'Maine',
    MD: 'Maryland', MA: 'Massachusetts', MI: 'Michigan', MN: 'Minnesota', MS: 'Mississippi', MO: 'Missouri', MT: 'Montana', NE: 'Nebraska', NV: 'Nevada',
    NH: 'New Hampshire', NJ: 'New Jersey', NM: 'New Mexico', NY: 'New York', NC: 'North Carolina', ND: 'North Dakota', OH: 'Ohio', OK: 'Oklahoma', OR: 'Oregon',
    PA: 'Pennsylvania', RI: 'Rhode Island', SC: 'South Carolina', SD: 'South Dakota', TN: 'Tennessee', TX: 'Texas', UT: 'Utah', VT: 'Vermont', VA: 'Virginia',
    WA: 'Washington', WV: 'West Virginia', WI: 'Wisconsin', WY: 'Wyoming', PR: 'Puerto Rico', VI: 'US Virgin Islands',
};
export function resolveState(s) {
    const t = s.trim();
    const name = STATE_CODES[t.toUpperCase()] ?? t;
    const norm = (x) => x.toLowerCase().replace(/[^a-z]/g, '').replace(/^theus|^us/, 'us');
    const hit = STATES_2026.find((r) => norm(r.state) === norm(name)) ?? STATES_2026.find((r) => norm(r.state).startsWith(norm(name)) && norm(name).length >= 4);
    if (!hit)
        throw new InputError(`No class of 2026 SAT report for "${s}". Use a two-letter code such as TX or a full name; covered: the 50 states, DC, Puerto Rico and US Virgin Islands.`);
    return hit;
}
// Nine states give the SAT to every 11th grader (College Board 2026 report footnote). Low means there reflect near-universal testing.
export const SCHOOL_DAY_STATES = ['Colorado', 'Connecticut', 'Delaware', 'Indiana', 'Michigan', 'New Hampshire', 'New Mexico', 'Rhode Island', 'West Virginia'];
const PARTICIPATION_NOTE = 'State averages are not comparable rankings of schools: states where few students take the SAT (often under 10% participation) have high means because mostly college-bound students test, while states that test every 11th grader have lower means.';
// ---------------------------------------------------------------- tool cores
export function getSatPercentile(score, sectionIn = 'total') {
    const section = resolveSection(sectionIn);
    checkScore(score, section);
    const p = percentiles(score, section);
    const band = section === 'total' ? bandFor(score) : null;
    const n = NATIONAL_2026;
    const vsMean = section === 'total' ? score - n.mean_total : section === 'rw' ? score - n.mean_rw : score - n.mean_math;
    const mean = section === 'total' ? n.mean_total : section === 'rw' ? n.mean_rw : n.mean_math;
    const summary = `An SAT ${SECTION_NAMES[section].replace(/ \(.*\)/, '').toLowerCase()} of ${score} is at the ${ordinal(p.user_group)} percentile of recent SAT takers (College Board user group percentile) and the ${ordinal(p.nationally_representative)} percentile of all US 11th and 12th graders (nationally representative percentile). ` +
        `It is ${Math.abs(vsMean)} points ${vsMean >= 0 ? 'above' : 'below'} the class of 2026 mean of ${mean} (${n.test_takers.toLocaleString('en-US')} test takers).` +
        (band ? ` ${band.pct}% of the class of 2026 (${band.test_takers.toLocaleString('en-US')} students) scored ${band.band}.` : '');
    return {
        score, section, section_name: SECTION_NAMES[section], percentiles: p,
        meaning: 'A percentile is the percent of the comparison group scoring at or below this score. User group = actual SAT takers who graduated in the past three school years. Nationally representative = weighted research sample of all US 11th and 12th graders, including students who do not take the SAT. "99+" means above the 99th percentile; "1-" below the 1st.',
        class_of_2026: { mean: mean, points_vs_mean: vsMean, score_band: band, test_takers: n.test_takers },
        as_of: DATA_DATE, source: PERCENTILE_SOURCE, sources: { percentiles: PERCENTILE_SOURCE, class_of_2026: n.source },
        more: MORE_CALC, related: [MORE_SAT], summary,
    };
}
export function getScoreForPercentile(percentile, sectionIn = 'total', group = 'user_group') {
    const section = resolveSection(sectionIn);
    if (!(percentile >= 1 && percentile <= 99))
        throw new InputError('percentile must be from 1 to 99.');
    const steps = section === 'total' ? Object.keys(TOTAL_PERCENTILES) : Object.keys(SECTION_PERCENTILES);
    const scores = steps.map(Number).sort((a, b) => a - b);
    const hit = scores.find((s) => { const p = percentiles(s, section); return pctNumber(group === 'user_group' ? p.user_group : p.nationally_representative) >= percentile; });
    if (hit === undefined)
        throw new InputError('No score reaches that percentile.');
    const p = percentiles(hit, section);
    const label = group === 'user_group' ? 'SAT takers (user group)' : 'all US 11th and 12th graders (nationally representative)';
    const summary = `The lowest SAT ${SECTION_NAMES[section].replace(/ \(.*\)/, '').toLowerCase()} at or above the ${percentile}th percentile of ${label} is ${hit} (listed percentile ${p[group]}). Same score: user group ${p.user_group}, nationally representative ${p.nationally_representative}.`;
    return {
        percentile, section, group, score: hit, percentiles_at_score: p,
        note: 'College Board publishes percentiles only at whole-number precision for each 10-point score; the score returned is the lowest one whose listed percentile is at or above the target.',
        as_of: DATA_DATE, source: PERCENTILE_SOURCE, more: MORE_CALC, related: [MORE_SAT], summary,
    };
}
function stateView(r) {
    const n = NATIONAL_2026;
    return {
        state: r.state, test_takers: r.test_takers, participation_rate_pct: r.participation_rate_pct,
        mean: { total: r.mean_total, rw: r.mean_rw, math: r.mean_math },
        met_benchmarks_pct: { both: r.met_both_pct, rw: r.met_rw_pct, math: r.met_math_pct, none: r.met_none_pct },
        score_percentiles: { p25: r.p25, p50: r.p50, p75: r.p75 },
        vs_national_mean_total: r.mean_total - n.mean_total, sat_school_day_state: SCHOOL_DAY_STATES.includes(r.state), source: r.source,
    };
}
export function getSatScoresByState(stateIn) {
    const r = resolveState(stateIn);
    const n = NATIONAL_2026;
    const v = stateView(r);
    const ranked = STATES_2026.filter((x) => x.participation_rate_pct !== null).sort((a, b) => b.mean_total - a.mean_total);
    const rank = ranked.findIndex((x) => x.state === r.state);
    const summary = `Class of 2026 SAT, ${r.state}: ${r.test_takers.toLocaleString('en-US')} test takers${r.participation_rate_pct !== null ? ` (${r.participation_rate_pct}% of graduates)` : ''}, mean total ${r.mean_total} (Reading and Writing ${r.mean_rw}, Math ${r.mean_math}), ${Math.abs(v.vs_national_mean_total)} points ${v.vs_national_mean_total >= 0 ? 'above' : 'below'} the national mean of ${n.mean_total}. ` +
        `${r.met_both_pct}% met both college readiness benchmarks.` + (r.p50 ? ` Middle 50% of total scores: ${r.p25.total} to ${r.p75.total} (median ${r.p50.total}).` : '') +
        (rank >= 0 ? ` Rank ${rank + 1} of ${ranked.length} by mean total among the states and DC.` : '') +
        (v.sat_school_day_state ? ' This state gives the SAT to all 11th graders, which lowers the mean.' : '') + ` ${PARTICIPATION_NOTE}`;
    return {
        class_of: 2026, ...v, rank_by_mean_total: rank >= 0 ? rank + 1 : null, ranked_of: ranked.length,
        national: { test_takers: n.test_takers, mean_total: n.mean_total, mean_rw: n.mean_rw, mean_math: n.mean_math, met_both_pct: n.met_both_pct, p25_total: n.p25_total, p50_total: n.p50_total, p75_total: n.p75_total },
        benchmarks: { rw: 480, math: 530 }, note: PARTICIPATION_NOTE,
        as_of: DATA_DATE, source: r.source, sources: { state_report: r.source, national_report: n.source, index: REPORT_PAGE }, more: MORE_SAT, related: [MORE_CALC], summary,
    };
}
export function rankStatesBySat(metric = 'mean_total', order = 'desc', limit = 51, minParticipation) {
    const key = {
        mean_total: (r) => r.mean_total, mean_math: (r) => r.mean_math, mean_rw: (r) => r.mean_rw,
        participation_rate: (r) => r.participation_rate_pct, met_both_benchmarks: (r) => r.met_both_pct, test_takers: (r) => r.test_takers,
    };
    if (!key[metric])
        throw new InputError('metric must be mean_total, mean_math, mean_rw, participation_rate, met_both_benchmarks or test_takers.');
    if (minParticipation !== undefined && !(minParticipation >= 0 && minParticipation <= 100))
        throw new InputError('min_participation_pct must be from 0 to 100.');
    const rows = STATES_2026.filter((r) => r.participation_rate_pct !== null && (minParticipation === undefined || r.participation_rate_pct >= minParticipation));
    const sorted = rows.sort((a, b) => (key[metric](b) - key[metric](a)) * (order === 'desc' ? 1 : -1) || a.state.localeCompare(b.state));
    const lim = Math.max(1, Math.min(51, Math.round(limit)));
    const out = sorted.slice(0, lim).map((r, i) => ({ rank: i + 1, state: r.state, value: key[metric](r), mean_total: r.mean_total, participation_rate_pct: r.participation_rate_pct, test_takers: r.test_takers }));
    const summary = `Class of 2026 SAT, states and DC ranked by ${metric.replace(/_/g, ' ')} (${order === 'desc' ? 'highest' : 'lowest'} first${minParticipation !== undefined ? `, participation at least ${minParticipation}%` : ''}): ${out.slice(0, 10).map((r) => `${r.rank}. ${r.state} ${r.value}${metric === 'participation_rate' || metric === 'met_both_benchmarks' ? '%' : ''}`).join(', ')}${out.length > 10 ? ', ...' : ''}. National mean total ${NATIONAL_2026.mean_total}. ${PARTICIPATION_NOTE}`;
    return {
        class_of: 2026, metric, order, min_participation_pct: minParticipation ?? null, count: out.length, states: out,
        excluded: 'Puerto Rico and the US Virgin Islands have no participation rate in their reports and are not ranked; get_sat_scores_by_state covers them.',
        note: PARTICIPATION_NOTE, as_of: DATA_DATE, source: REPORT_PAGE, more: MORE_SAT, summary,
    };
}
